"""Disposable design probes; this is not product code or a provider integration."""
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
import json
from pathlib import Path
import sqlite3
from tempfile import TemporaryDirectory
from threading import Barrier
from types import MappingProxyType


@dataclass(frozen=True)
class ProviderSpec:
    interactive: bool


def methods(registry, *, interactive_only=False):
    return tuple(name for name, spec in registry.items()
                 if not interactive_only or spec.interactive)


class OperationKeyConflict(ValueError):
    pass


def record(database, method, amount, key, *, crash_before_commit=False):
    if amount <= 0:
        raise ValueError("invalid payment")
    connection = sqlite3.connect(database, timeout=5)
    try:
        connection.execute("BEGIN IMMEDIATE")
        row = connection.execute(
            "SELECT method, amount, operation FROM ledger WHERE operation = ?", (key,)
        ).fetchone()
        if row is not None:
            if row[:2] != (method, amount):
                raise OperationKeyConflict(key)
        else:
            connection.execute(
                "INSERT INTO ledger(operation, method, amount) VALUES (?, ?, ?)",
                (key, method, amount),
            )
            row = (method, amount, key)
        if crash_before_commit:
            raise RuntimeError("simulated failure before commit")
        connection.commit()
        return dict(zip(("method", "amount", "operation"), row))
    except BaseException:
        connection.rollback()
        raise
    finally:
        connection.close()


def count(database, key):
    with sqlite3.connect(database) as connection:
        return connection.execute(
            "SELECT COUNT(*) FROM ledger WHERE operation = ?", (key,)
        ).fetchone()[0]


def concurrent_pair(database, requests):
    barrier = Barrier(2)
    def run(request):
        barrier.wait(timeout=5)
        try:
            return {"status": "recorded", "receipt": record(database, *request)}
        except OperationKeyConflict:
            return {"status": "conflict"}
    with ThreadPoolExecutor(max_workers=2) as executor:
        return list(executor.map(run, requests))


def main():
    output = Path(__file__).resolve().parent
    results = {}

    base = {"card": ProviderSpec(True), "invoice": ProviderSpec(False)}
    projections = []
    for interactive in (False, True):
        registry = MappingProxyType({**base, "bank_transfer": ProviderSpec(interactive)})
        assert methods(registry) == ("card", "invoice", "bank_transfer")
        expected = ("card", "bank_transfer") if interactive else ("card",)
        assert methods(registry, interactive_only=True) == expected
        assert "invoice" not in methods(registry, interactive_only=True)
        projections.append({"bank_interactive": interactive, "billing": methods(registry),
                            "ui": methods(registry, interactive_only=True)})
    results["registry_projections"] = projections

    with TemporaryDirectory(prefix="ledger-probe-", dir=output) as directory:
        database = Path(directory) / "ledger.sqlite3"
        with sqlite3.connect(database) as connection:
            connection.execute("""CREATE TABLE ledger (
                operation TEXT NOT NULL PRIMARY KEY,
                method TEXT NOT NULL,
                amount INTEGER NOT NULL CHECK(amount > 0)
            )""")

        request = ("bank_transfer", 12500, "same-key")
        same = concurrent_pair(database, (request, request))
        assert same[0] == same[1]
        assert count(database, "same-key") == 1
        assert record(database, *request) == same[0]["receipt"]
        results["concurrent_identical_requests"] = {"results": same, "rows": 1,
                                                     "retry_on_new_connection": "same receipt"}

        different = concurrent_pair(database, (("bank_transfer", 12500, "conflict-key"),
                                                ("bank_transfer", 12600, "conflict-key")))
        assert sorted(result["status"] for result in different) == ["conflict", "recorded"]
        assert count(database, "conflict-key") == 1
        results["concurrent_conflicting_requests"] = {"results": different, "rows": 1}

        independent = concurrent_pair(database, (("card", 100, "card-key"),
                                                  ("invoice", 200, "invoice-key")))
        assert all(result["status"] == "recorded" for result in independent)
        results["independent_two_writer_requests"] = "both recorded"

        try:
            record(database, "bank_transfer", 100, "rollback-key", crash_before_commit=True)
        except RuntimeError:
            pass
        assert count(database, "rollback-key") == 0
        record(database, "bank_transfer", 100, "rollback-key")
        assert count(database, "rollback-key") == 1
        results["failure_before_commit"] = "rolled back; retry records one row"

        try:
            record(database, "card", 0, "invalid-key")
        except ValueError:
            pass
        else:
            raise AssertionError("nonpositive amount accepted")
        assert count(database, "invalid-key") == 0
        results["nonpositive_amount"] = "rejected without row"

        try:
            with sqlite3.connect(database) as connection:
                connection.execute("INSERT INTO ledger VALUES (?, ?, ?)",
                                   ("same-key", "card", 300))
        except sqlite3.IntegrityError:
            results["database_duplicate_constraint"] = "rejected"
        else:
            raise AssertionError("duplicate key accepted")

    results["limits"] = [
        "SQLite is a standard-library feasibility probe, not the supplied production storage adapter.",
        "Amounts are integers only in this probe; the supplied payments amount unit and type are unspecified.",
        "Simulated pre-commit exceptions do not establish operating-system crash or power-loss durability.",
        "No bank API, external settlement, remote idempotency, or end-to-end compatibility was exercised.",
        "Both bank visibility settings were tested without selecting a product requirement."
    ]
    (output / "probe-results.json").write_text(json.dumps(results, indent=2) + "\n")
    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main()

