"""Observe supplied behavior without changing or byte-compiling its files."""

import ast
import hashlib
import importlib
import json
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
sys.dont_write_bytecode = True
sys.path.insert(0, str(ROOT / "project" / "src"))
observations = []


def observe(name, condition, evidence):
    assert condition, (name, evidence)
    observations.append({"name": name, "observed": evidence})


payments = importlib.import_module("payments")
mobile = importlib.import_module("mobile")
billing = importlib.import_module("billing")
ui = importlib.import_module("ui")
v1 = importlib.import_module("v1")
providers = importlib.import_module("payments.providers").PROVIDERS

receipt = payments.pay("card", 2500, "probe-1")
observe("public payment result", receipt == {
    "method": "card", "amount": 2500, "operation": "probe-1"
}, receipt)

for method, amount, key in [("missing", 2500, "probe-2"), ("card", 0, "probe-3")]:
    try:
        payments.pay(method, amount, key)
    except ValueError as error:
        observe("public validation rejection", str(error) == "invalid payment", {
            "method": method, "amount": amount, "error": str(error)
        })
    else:
        raise AssertionError("invalid public payment was accepted")

bypass = mobile.charge(-1, "probe-4")
observe("mobile bypasses validation", bypass["amount"] == -1, bypass)
observe("low-level writer is also exported", hasattr(payments, "write"), {
    "payments.write_callable": callable(payments.write)
})
observe("billing currently covers registry", set(billing.BILLING_METHODS) == set(providers), {
    "billing": billing.BILLING_METHODS, "registry": list(providers)
})
visible = [name for name, provider in providers.items() if provider["interactive"]]
observe("UI currently matches interactive subset", ui.VISIBLE_METHODS == visible, {
    "UI": ui.VISIBLE_METHODS, "derived_interactive_subset": visible
})

# Mutate a copied dictionary only; the supplied modules remain unchanged.
extended = {**providers, "bank_transfer": {"interactive": True}}
observe("copied consumer lists will omit a new registration", (
    "bank_transfer" in extended
    and "bank_transfer" not in billing.BILLING_METHODS
    and "bank_transfer" not in ui.VISIBLE_METHODS
), {"probe_only_visibility": True, "actual_bank_transfer_visibility": "unspecified"})

events = []
wire = v1.WireReceipt("invoice-7", 2500)


def authorize(invoice_id):
    events.append(["authorize", invoice_id])


def provider(value):
    events.append(["provider", list(value)])
    return "provider-result"


for _ in range(2):
    assert v1.submit(wire, authorize, provider) == "provider-result"
observe("v1 authorizes every invocation before provider", [e[0] for e in events] == [
    "authorize", "provider", "authorize", "provider"
], events.copy())

events.clear()


def deny(invoice_id):
    events.append(["deny", invoice_id])
    raise PermissionError("denied")


try:
    v1.submit(wire, deny, provider)
except PermissionError:
    observe("v1 denial does not invoke provider", events == [["deny", "invoice-7"]], events)
else:
    raise AssertionError("authorization denial was swallowed")

imports = []
for path in sorted((ROOT / "project" / "src").rglob("*.py")):
    for node in ast.walk(ast.parse(path.read_text(), filename=str(path))):
        if isinstance(node, ast.ImportFrom) and node.module == "payments._ledger":
            imports.append({"path": str(path.relative_to(ROOT)), "line": node.lineno})
observe("source import check identifies actual bypass", imports == [
    {"path": "project/src/mobile.py", "line": 1}
], imports)

hashes = {
    str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()
    for folder in ["project", "skills"]
    for path in sorted((ROOT / folder).rglob("*"))
    if path.is_file()
}
(ROOT / "output" / "input-sha256.json").write_text(json.dumps(hashes, indent=2) + "\n")
result = {"status": "passed", "observation_count": len(observations), "observations": observations}
(ROOT / "output" / "probe-results.json").write_text(json.dumps(result, indent=2) + "\n")
print(json.dumps(result, indent=2))
